                                </button>
                            </div>
                            <div className="h-safe-bottom w-full shrink-0" />
                       </div>
                  </div>
              )}

              {/* LEVELS */}
              {screen === 'levels' && selectedDifficulty && (
                  <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
                      <div className="w-full max-w-md flex items-start px-6 pt-[70px] pb-6 relative shrink-0">
                        <button onClick={handleLevelBack} className="absolute left-6 top-[70px] p-2 rounded-full hover:bg-stone-200 transition -ml-2"><Icons.Back className="w-6 h-6" /></button>
                        <div className="w-full text-center mt-2 pointer-events-none">
