                                          {bestTime && <div className="absolute bottom-1.5 inset-x-0 text-center"><span className="text-[10px] text-stone-400 font-bold tracking-tight block">{formatTimeShort(bestTime)}</span></div>}
                                          {isInProgress && !bestTime && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 absolute bottom-2 left-1/2 -translate-x-1/2"></div>}
                                      </button>
                                  );
                              })}
                          </div>
                          <div className="h-safe-bottom w-full shrink-0" />
