// Fullscreen Background Component
const Background = ({ className }: { className: string }) => (
    <div className={`fixed inset-0 w-full h-full -z-50 bg-cover bg-center bg-no-repeat pointer-events-none transition-all duration-700 ease-in-out bg-stone-50 ${className}`} />
